new file mode 100644
index 0000000..e5c5eb9
--- /dev/null
+++ b/specs/1/SPEC.md
@@ -0,0 +1,32 @@
+# Spec: issue 1, the README has no "run it" section
+
+## Outcome
+
+A volunteer who opens `README.md` can start the web page, run the desk CLI and run the tests by
+copying commands from one short section.
+
+## Requirements
+
+- The system shall have a section in `README.md` whose heading is "Run it".
+- When a reader looks in the "Run it" section for the web page, the system shall show the command `bun src/server.ts`.
+- When a reader looks in the "Run it" section for the desk CLI, the system shall show a command that starts with `bun src/desk.ts` and name the `overdue` command.
+- When a reader looks in the "Run it" section for the tests, the system shall show the command `bun test`.
+- Where the section names a script file, the system shall name a file that exists in the app.
+
+## Must not change
+
+- Nothing under `src/` changes.
+- Nothing under `tests/` that exists today changes.
+- The "Folders" table in `README.md` stays as it is.
+- `package.json` stays as it is.
+
+## Out of scope
+
+- Adding a `desk` or `start` script to `package.json`.
+- Installing Bun or the dependencies.
+- Describing the seed data or the web page's API.
+
+## Done when
+
+- `bun run gate` exits 0 with the new tests passing.
+- The new tests in `tests/docs/readme.test.ts` pass.
diff --git a/tests/docs/readme.test.ts b/tests/docs/readme.test.ts
new file mode 100644
index 0000000..e8415fd
--- /dev/null
+++ b/tests/docs/readme.test.ts
@@ -0,0 +1,46 @@
+import { expect, test } from "bun:test";
+import { existsSync, readFileSync } from "node:fs";
+import { join } from "node:path";
+
+const appFolder = join(import.meta.dir, "..", "..");
+const readme = readFileSync(join(appFolder, "README.md"), "utf8");
+
+function runItSection(): string {
+  const start = readme.search(/^##\s+Run it\s*$/m);
+  if (start === -1) {
+    return "";
+  }
+  const rest = readme.slice(start).replace(/^##\s+Run it\s*$/m, "");
+  const next = rest.search(/^##\s/m);
+  if (next === -1) {
+    return rest;
+  }
+  return rest.slice(0, next);
+}
+
+test("the README has a Run it section", () => {
+  expect(runItSection().trim().length).toBeGreaterThan(0);
+});
+
+test("the Run it section shows how to start the web page", () => {
+  expect(runItSection()).toContain("bun src/server.ts");
+});
+
+test("the Run it section shows how to run the desk CLI", () => {
+  const section = runItSection();
+  expect(section).toContain("bun src/desk.ts");
+  expect(section).toContain("overdue");
+});
+
+test("the Run it section shows how to run the tests", () => {
+  expect(runItSection()).toMatch(/`bun test`|^bun test$/m);
+});
+
+test("every script file the Run it section names exists", () => {
+  const section = runItSection();
+  const named = section.match(/src\/[\w/]+\.ts/g) ?? [];
+  expect(named.length).toBeGreaterThan(0);
+  for (const file of named) {
+    expect(existsSync(join(appFolder, file))).toBe(true);
+  }
+});

